const raw = $input.first().json;
let task;
try { task = typeof raw.task === 'string' ? JSON.parse(raw.task) : raw.task; }
catch (e) { throw new Error('task is not valid JSON'); }
if (!task || typeof task !== 'object') throw new Error('task is missing');
for (const k of ['task_id', 'user_id', 'goal']) {
  if (!task[k]) throw new Error('task missing ' + k);
}
task.agent = 'follow_up';
task.mode = 'propose';          // this workflow can never run in another mode
task.inputs = task.inputs || {};
return [{ json: { user_id: String(task.user_id), task } }];

const profile = $('Load profile').first().json;
const { task } = $('Parse task').first().json;
const j = (v, fallback) => {
  try { return typeof v === 'string' ? JSON.parse(v) : (v ?? fallback); } catch (e) { return fallback; }
};
const tz = profile.tz || 'Asia/Kolkata';
const prefs = j(profile.preferences, {});
const lookback = Number(task.inputs.lookback_days || prefs.follow_up_lookback_days || 3);
return [{ json: {
  task,
  ctx: {
    user_id: profile.user_id, user_name: profile.name, user_email: profile.email,
    tz, now: DateTime.now().setZone(tz).toISO(),
    lookback_days: lookback,
    window_start: DateTime.now().setZone(tz).minus({ days: lookback }).toISO(),
    working_hours: j(profile.working_hours, { start: '09:30', end: '18:30' }),
    calendars: j(profile.calendars, []), preferences: prefs,
    default_duration: prefs.default_duration || 30,
    company_domains: prefs.company_domains || [],
    vip: prefs.vip || []
  }
} }];

// Structural check. Drops malformed proposals and recomputes "external" from addresses.
const ctx = $('Build context').first().json.ctx;
const out = $input.first().json;
const ALLOWED = ['send_email', 'create_task', 'create_event', 'update_event'];
const domains = (ctx.company_domains || []).map(d => String(d).toLowerCase());
const isInternal = (e) => domains.includes((String(e || '').toLowerCase().split('@')[1]) || '');
const asList = (v) => Array.isArray(v) ? v.map(String).filter(Boolean) : (v ? String(v).split(',').map(s => s.trim()).filter(Boolean) : []);
const notes = [];
const valid = [];
(out.proposals || []).forEach((p, i) => {
  const label = 'proposal ' + (i + 1);
  if (!p || !ALLOWED.includes(p.type)) { notes.push(label + ' dropped: unknown type'); return; }
  if (!p.summary) { notes.push(label + ' dropped: missing summary'); return; }
  const to = asList(p.to), cc = asList(p.cc), attendees = asList(p.attendees);
  if (p.type === 'send_email' && (!to.length || !p.subject || !p.body)) { notes.push(label + ' dropped: email needs to, subject and body'); return; }
  if (p.type === 'create_task' && !p.title) { notes.push(label + ' dropped: task needs a title'); return; }
  if (p.type === 'update_event' && !p.event_id) { notes.push(label + ' dropped: missing event_id'); return; }
  if (p.type === 'create_event' || p.type === 'update_event') {
    const s = DateTime.fromISO(String(p.start || '')), e = DateTime.fromISO(String(p.end || ''));
    if (!s.isValid || !e.isValid || e <= s) { notes.push(label + ' dropped: invalid start/end'); return; }
    if (s < DateTime.now()) { notes.push(label + ' dropped: starts in the past'); return; }
  }
  const people = p.type === 'send_email' ? to.concat(cc) : attendees;
  valid.push(Object.assign({}, p, { to, cc, attendees,
    calendar_id: p.calendar_id || 'primary',
    affects: people.length ? people : asList(p.affects),
    external: people.some(a => !isInternal(a)) }));
});
const proposals = valid.slice(0, 8);
let status = ['ok', 'needs_input', 'no_action'].includes(out.status) ? out.status : 'ok';
if (status === 'ok' && proposals.length === 0) status = 'no_action';
return [{ json: { status, results: out.results || {}, proposals, notes: [out.notes].concat(notes).filter(Boolean).join(' | ') } }];

const meta = $input.first().json;
const user_id = $('Parse task').first().json.user_id;
const agent = 'follow_up';                        // hard-coded per workflow
const pid = (i) => 'fu-' + String($execution.id) + '-' + (i + 1);   // Build response uses the same rule
return meta.proposals.map((p, i) => ({ json: {
  proposal_id: pid(i), user_id, agent,
  action: JSON.stringify(p), summary: p.summary, external: !!p.external, status: 'pending'
} }));

const meta = $('Validate output').first().json;
const pid = (i) => 'fu-' + String($execution.id) + '-' + (i + 1);   // same rule as Split proposals
return [{ json: {
  status: meta.status,
  results: meta.results,
  proposed_actions: meta.proposals.map((p, i) => ({
    proposal_id: pid(i), summary: p.summary, affects: p.affects || [], external: !!p.external
  })),
  notes: meta.notes || ''
} }];
